{"command":"create","file_text":"//! picocolors-compatible ANSI coloring.
//!
//! Replicates the subset of the `picocolors` package used by jscodeshift's
//! runner output. Colors are only emitted when color support is detected using
//! the same rules as picocolors; otherwise the plain string is returned.

use std::env;
use std::io::IsTerminal;

fn color_supported() -> bool {
    let env = env::vars();
    // NO_COLOR in env disables; --no-color in argv disables.
    let no_color = env::var_os("NO_COLOR").is_some()
        || std::env::args().any(|a| a == "--no-color");
    if no_color {
        return false;
    }
    if env::var_os("FORCE_COLOR").is_some() {
        return true;
    }
    if std::env::args().any(|a| a == "--color") {
        return true;
    }
    if cfg!(windows) {
        return true;
    }
    if std::io::stdout().is_terminal() && env::var("TERM").as_deref() != Ok("dumb") {
        return true;
    }
    env::var_os("CI").is_some()
}

fn paint(open: &str, close: &str, input: &str, enabled: bool) -> String {
    if !enabled {
        return input.to_string();
    }
    let mut result = String::with_capacity(open.len() + input.len() + close.len());
    result.push_str(open);
    // picocolors escapes occurrences of `close` inside the input by replacing
    // them with `open` (the same opener), then appends `close`.
    let mut cursor = 0usize;
    let bytes = input.as_bytes();
    while let Some(rel) = input[cursor..].find(close) {
        let idx = cursor + rel;
        result.push_str(&input[cursor..idx]);
        result.push_str(open);
        cursor = idx + close.len();
        let _ = bytes;
    }
    result.push_str(&input[cursor..]);
    result.push_str(close);
    result
}

#[derive(Clone, Copy)]
pub struct Colors {
    enabled: bool,
}

impl Colors {
    pub fn new() -> Self {
        Colors {
            enabled: color_supported(),
        }
    }

    fn p(&self, open: &str, close: &str, input: &str) -> String {
        paint(open, close, input, self.enabled)
    }

    pub fn red(&self, input: &str) -> String {
        self.p("\u{1b}[31m", "\u{1b}[39m", input)
    }
    pub fn green(&self, input: &str) -> String {
        self.p("\u{1b}[32m", "\u{1b}[39m", input)
    }
    pub fn yellow(&self, input: &str) -> String {
        self.p("\u{1b}[33m", "\u{1b}[39m", input)
    }
    pub fn blue(&self, input: &str) -> String {
        self.p("\u{1b}[34m", "\u{1b}[39m", input)
    }
    pub fn white(&self, input: &str) -> String {
        self.p("\u{1b}[37m", "\u{1b}[39m", input)
    }
    pub fn bg_red(&self, input: &str) -> String {
        self.p("\u{1b}[41m", "\u{1b}[49m", input)
    }
    pub fn bg_green(&self, input: &str) -> String {
        self.p("\u{1b}[42m", "\u{1b}[49m", input)
    }
    pub fn bg_yellow(&self, input: &str) -> String {
        self.p("\u{1b}[43m", "\u{1b}[49m", input)
    }
    pub fn bg_blue(&self, input: &str) -> String {
        self.p("\u{1b}[44m", "\u{1b}[49m", input)
    }
