{"command":"create","file_text":"//! Port of `src/argsParser.js`.
//!
//! Replicates the externally observable behavior of the original argument
//! parser: option specs, help-text formatting, value/list/flag handling,
//! unknown-option pass-through, JSON value coercion, choices validation, and
//! exit codes for errors, help, and version callbacks.

use std::collections::BTreeMap;
use std::process::exit;

/// A custom sentinel distinguished from any real value, mirroring the JS
/// `missingValue` symbol used by the original parser.
#[derive(Clone, Debug, PartialEq)]
pub struct MissingValue;

/// Possible parsed value kinds. Numbers, booleans, strings, JSON arrays/objects
/// are represented via the JSON enum so that custom option values can be
/// round-tripped to the transform bridge.
#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

impl Value {
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }
    pub fn as_number(&self) -> Option<f64> {
        match self {
            Value::Number(n) => Some(*n),
            _ => None,
        }
    }
    pub fn as_string(&self) -> Option<&str> {
        match self {
            Value::String(s) => Some(s.as_str()),
            _ => None,
        }
    }
}

/// Spec describing a single option.
pub struct OptionSpec {
    pub key: String,
    pub full: String,
    pub abbr: Option<String>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<String>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub display_index: i64,
    /// If set, invoking this option terminates parsing by printing the
    /// returned string and exiting with code 0.
    pub callback: Option<fn() -> String>,
    /// Optional value preprocessor (e.g. `Number` or JSON-file read).
    pub process: Option<fn(&str) -> Value>,
}

pub struct Parsed {
    pub options: BTreeMap<String, Value>,
    pub positional: Vec<Value>,
}

pub struct Parser {
    specs: Vec<OptionSpec>,
}

impl Parser {
    pub fn new(specs: Vec<OptionSpec>) -> Self {
        Parser { specs }
    }

    fn get_help_text(&self) -> String {
        get_help_text(&self.specs)
    }

    pub fn parse(&self, args: &[String]) -> Parsed {
        let missing = Value::String("__jscodeshift_missing_value__".to_string());

        // prepareOptions: index by --full, -abbr, --no-full (if flag). Also add
        // a synthetic `help` option.
        // The original injects `help` into the options object before indexing.
        let mut all_specs: Vec<OptionSpec> = self.specs.clone();
        // `help` option references the full set; we build help text from
        // specs including help itself (display_index 5).
        all_specs.push(OptionSpec {
            key: "help".to_string(),
            full: "help".to_string(),
            abbr: Some("h".to_string()),
            flag: false,
            list: false,
            default: None,
            default_help: None,
            choices: None,
            help: Some("print this help and exit".to_string()),
            metavar: None,
            display_index: 5,
            callback: Some(help_callback),
            process: None,
        });

        // Build lookup tables.
        let mut by_long: BTreeMap<String, usize> = BTreeMap::new();
        let mut by_short: BTreeMap<String, usize> = BTreeMap::new();
        let mut by_no: BTreeMap<String, usize> = BTreeMap::new();
        // For lookup, specs need `full` set. The user-provided specs already set
        // `full` via the helper API; ensure help has full.
        for (i, s) in all_specs.iter().enumerate() {
            by_long.insert(format!("--{}", s.full), i);
            if let Some(a) = &s.abbr {
                by_short.insert(format!("-{}", a), i);
            }
            if s.flag {
                by_no.insert(format!("--no-{}", s.full), i);
            }
        }

        // Build initial parsedOptions from defaults / list.
        let mut options: BTreeMap<String, Value> = BTreeMap::new();
        for s in &self.specs {
            if let Some(d) = &s.default {
                options.insert(s.key.clone(), d.clone());
            } else if s.list {
                options.insert(s.key.clone(), Value::Array(vec![]));
            }
        }
        let mut positional: Vec<Value> = Vec::new();

        let is_option = |v: &str| v.starts_with("--") || v == "-" || v.starts_with("-") && v.len() > 1 && v.chars().nth(1).map(|c| !c.is_ascii_digit()).unwrap_or(true);
        // Note: the original isOption is /^--?/ which matches anything starting
        // with `-` (including "-5" -> true, since "-" matches "--?" via "-").
        // Replicate exactly: starts with "-" .
        let is_option = |v: &str| v.starts_with('-');

        let n = args.len();
        let mut i = 0usize;
        // Track which option object a dynamic unknown option maps to so that
        // subsequent encounters reuse the same key/list behavior.
        // We model "seen" via the options map itself (presence + non-true).

        while i < n {
            let arg = &args[i];
            if is_option(arg.as_str()) {
                let mut option_name = arg.clone();
                let mut value: Option<String> = None;
                if let Some(eq) = arg.find('=') {
                    option_name = arg[..eq].to_string();
                    value = Some(arg[eq + 1..].to_string());
                }

                // Resolve known option.
                let known_idx = if let Some(&idx) = by_long.get(&option_name) {
                    Some(idx)
                } else if let Some(&idx) = by_short.get(&option_name) {
                    Some(idx)
                } else if let Some(&idx) = by_no.get(&option_name) {
                    Some(idx)
                } else {
                    None
                };

                let spec_key: String;
                let spec_full: String;
                let is_flag: bool;
                let is_list: bool;
                let has_callback: bool;
                let processor: Option<fn(&str) -> Value>;

                if let Some(idx) = known_idx {
                    let s = &all_specs[idx];
                    spec_key = s.key.clone();
                    spec_full = s.full.clone();
                    is_flag = s.flag;
                    has_callback = s.callback.is_some();
                    processor = s.process;
                    // For known list options, list is true.
                    is_list = s.list;
                } else {
                    // Unknown option: passed along.
                    // realOptionName = optionName.replace(/^--?(no-)?/, '')
                    let real = option_name
                        .strip_prefix('-')
                        .map(|r| {
                            if let Some(rest) = r.strip_prefix("no-") {
                                rest.to_string()
                            } else {
                                r.to_string()
                            }
                        })
                        .unwrap_or(option_name.clone());
                    // Also handle the leading "--": strip prefix "--no-" or "--" or "-".
                    let real = strip_prefix_option(&option_name);

                    let prev = options.get(&real);
                    // isList = parsedOptions.hasOwnProperty(real) && parsedOptions[real] !== true
                    let is_list_dyn = prev.is_some() && !matches!(prev, Some(Value::Bool(true)));

                    // flag if not seen before, value is null, and next arg is an option.
                    let flag_dyn = prev.is_none()
                        && value.is_none()
                        && (i + 1 < n && is_option(&args[i + 1]));

                    spec_key = real.clone();
                    spec_full = real.clone();
                    is_flag = flag_dyn;
                    is_list = is_list_dyn;
                    has_callback = false;
                    processor = Some(parse_json_value);

                    if is_list {
                        // convert current value to list if needed
                        let cur = options.get(&real).cloned();
                        match cur {
                            Some(Value::Bool(true)) => {
                                options.insert(real.clone(), Value::Array(vec![]));
                            }
                            Some(Value::Array(_)) => {}
                            Some(other) => {
                                options.insert(real.clone(), Value::Array(vec![other]));
                            }
                            None => {}
                        }
                    }
                }

                if has_callback {
                    let cb = all_specs
                        .iter()
                        .find(|s| s.key == spec_key)
                        .and_then(|s| s.callback)
                        .unwrap();
                    let text = cb();
                    throw_error(0, &text, None);
                } else if is_flag {
                    let v = if option_name.starts_with("--no-") {
                        Value::Bool(false)
                    } else if let Some(val) = &value {
                        Value::Bool(val == "1")
                    } else {
                        Value::Bool(true)
                    };
                    options.insert(spec_key, v);
                } else {
                    // non-flag
                    let mut val = value;
                    if val.is_none() && i + 1 < n && !is_option(&args[i + 1]) {
                        val = Some(args[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = val {
                        let processed = if let Some(p) = processor {
                            p(&v)
                        } else {
                            Value::String(v.clone())
                        };
                        if is_list {
                            let entry = options.entry(spec_key).or_insert_with(|| Value::Array(vec![]));
                            if let Value::Array(arr) = entry {
                                arr.push(processed);
                            } else {
                                options.insert(spec_full.clone(), Value::Array(vec![processed]));
                            }
                        } else {
                            options.insert(spec_key, processed);
                        }
                    } else {
                        options.insert(spec_key, missing.clone());
                    }
                }
            } else {
                // positional
                if let Ok(num) = arg.parse::<f64>() {
                    // /^\d+$/ only matches integer digit strings.
                    if arg.chars().all(|c| c.is_ascii_digit()) {
                        positional.push(Value::Number(num));
                    } else {
                        positional.push(Value::String(arg.clone()));
                    }
                } else {
                    positional.push(Value::String(arg.clone()));
                }
            }
            i += 1;
        }

        // Check for missing values.
        for (name, v) in &options {
            if let Value::String(s) = v {
                if s == "__jscodeshift_missing_value__" {
                    let full = self
                        .specs
                        .iter()
                        .find(|sp| sp.key == *name)
                        .map(|sp| sp.full.clone())
                        .unwrap_or_else(|| name.clone());
                    let msg = format!("Missing value: --{} requires a value", full);
                    throw_error(1, &msg, Some(self.get_help_text()));
                }
            }
        }

        // Validate choices.
        let mut errors: Vec<String> = Vec::new();
        for s in &self.specs {
            if let Some(choices) = &s.choices {
                let val = options.get(&s.key);
                let ok = match val {
                    None => true,
                    Some(v) => choices.iter().any(|c| values_equal(c, v)),
                };
                if !ok {
                    let choices_str = choices
                        .iter()
                        .map(value_repr)
                        .collect::<Vec<_>>()
                        .join(",");
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        s.full, choices_str
                    ));
                }
            }
        }
        if !errors.is_empty() {
            let msg = errors.join("\n");
            throw_error(1, &msg, Some(self.get_help_text()));
        }

        Parsed { options, positional }
    }
}

fn help_callback() -> String {
    // Unused directly: the real help text is generated from the parser's specs.
    String::new()
}

fn strip_prefix_option(name: &str) -> String {
    // Replicate optionName.replace(/^--?(no-)?/, '')
    let s = name.strip_prefix('-').unwrap_or(name);
    let s = s.strip_prefix('-').unwrap_or(s);
    if let Some(rest) = s.strip_prefix("no-") {
        rest.to_string()
    } else {
        s.to_string()
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Null, Value::Null) => true,
        _ => false,
    }
}

fn value_repr(v: &Value) -> String {
    match v {
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => {
            if n.fract() == 0.0 {
                format!("{}", *n as i64)
            } else {
                format!("{}", n)
            }
        }
        Value::String(s) => s.clone(),
        Value::Null => "null".to_string(),
        Value::Array(a) => format!("{:?}", a),
        Value::Object(o) => format!("{:?}", o),
    }
}

fn parse_json_value(v: &str) -> Value {
    // Try JSON.parse; fall back to the raw string. This mirrors the
    // unknown-option processor used by the original parser.
    if let Ok(val) = json::parse(v) {
        return val;
    }
    Value::String(v.to_string())
}

/// Throws (exits) with a constructed error message, mirroring throwError.
pub fn throw_error(exit_code: i32, message: &str, help_text: Option<String>) -> ! {
    let full = match help_text {
        Some(h) => format!("{}\n\n---\n\n{}", message, h),
        None => message.to_string(),
    };
    if exit_code == 0 {
        // write to stdout
        use std::io::Write;
        let _ = std::io::stdout().write_all(full.as_bytes());
    } else {
        use std::io::Write;
        let _ = std::io::stderr().write_all(full.as_bytes());
    }
    exit(exit_code);
}

/// formatOption from the original parser.
fn format_option(opt: &OptionSpec) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    let flag_prefix = if opt.flag { "(no-)" } else { "" };
    text.push_str(&format!("--{}{}", flag_prefix, opt.full));
    if let Some(choices) = &opt.choices {
        text.push_str(&format!("={}", choices.iter().map(value_repr).collect::<Vec<_>>().join("|")));
    } else if let Some(mv) = &opt.metavar {
        text.push_str(&format!("={}", mv));
    }
    if opt.list {
        text.push_str(" ...");
    }
    if opt.default_help.is_some() || opt.default.is_some() || opt.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len());
        }
        let text_length = text.len();
        if let Some(help) = &opt.help {
            text.push_str(help);
        }
        if opt.default_help.is_some() || opt.default.is_some() {
            if opt.help.is_some() {
                text.push('\n');
            }
            let default = opt
                .default_help
                .clone()
                .unwrap_or_else(|| opt.default.as_ref().map(value_repr).unwrap_or_default());
            text.push_str(&format!("{}(default: {})", " ".repeat(text_length), default));
        }
    }
    text
}

fn get_help_text(specs: &[OptionSpec]) -> String {
    let mut opts: Vec<&OptionSpec> = specs.iter().collect();
    opts.sort_by_key(|o| o.display_index);
    let mut text = String::new();
    text.push_str("\nUsage: jscodeshift [OPTION]... PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t URL PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n");
    text.push_str("\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n");
    text.push_str("If --stdin is set, each line of the standard input is used as a path.\n");
    text.push_str("\nOptions:\n");
    text.push_str("\"...\" behind an option means that it can be supplied multiple times.\n");
    text.push_str("All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n");
    text.push_str("\n");
    let rendered: Vec<String> = opts.iter().map(|o| format_option(o)).collect();
    text.push_str(&rendered.join("\n"));
    text.push('\n');
    // trimLeft: remove leading whitespace/newlines.
    text.trim_start().to_string()
}

pub mod json {
    use super::Value;
    use std::collections::BTreeMap;

    /// Minimal JSON parser supporting the value types used by jscodeshift
    /// options (objects, arrays, strings, numbers, booleans, null).
    pub fn parse(input: &str) -> Result<Value, String> {
        let mut p = Parser {
            chars: input.chars().collect(),
            pos: 0,
        };
        p.skip_ws();
        let v = p.parse_value()?;
        p.skip_ws();
        if p.pos != p.chars.len() {
            return Err("trailing characters".to_string());
        }
        Ok(v)
    }

    struct Parser {
        chars: Vec<char>,
        pos: usize,
    }

    impl Parser {
        fn skip_ws(&mut self) {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
        }
        fn parse_value(&mut self) -> Result<Value, String> {
            self.skip_ws();
            match self.chars.get(self.pos).copied() {
                Some('{') => self.parse_object(),
                Some('[') => self.parse_array(),
                Some('"') => self.parse_string().map(Value::String),
                Some('t') => self.parse_lit("true", Value::Bool(true)),
                Some('f') => self.parse_lit("false", Value::Bool(false)),
                Some('n') => self.parse_lit("null", Value::Null),
                Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number(),
                _ => Err("unexpected token".to_string()),
            }
        }
        fn parse_lit(&mut self, lit: &str, val: Value) -> Result<Value, String> {
            for c in lit.chars() {
                if self.chars.get(self.pos) == Some(&c) {
                    self.pos += 1;
                } else {
                    return Err("invalid literal".to_string());
                }
            }
            Ok(val)
        }
        fn parse_array(&mut self) -> Result<Value, String> {
            self.pos += 1; // [
            let mut arr = Vec::new();
            self.skip_ws();
            if self.chars.get(self.pos) == Some(&']') {
                self.pos += 1;
                return Ok(Value::Array(arr));
            }
            loop {
                let v = self.parse_value()?;
                arr.push(v);
                self.skip_ws();
                match self.chars.get(self.pos) {
                    Some(',') => {
                        self.pos += 1;
                        self.skip_ws();
                    }
                    Some(']') => {
                        self.pos += 1;
                        return Ok(Value::Array(arr));
                    }
                    _ => return Err("expected , or ]".to_string()),
                }
            }
        }
        fn parse_object(&mut self) -> Result<Value, String> {
            self.pos += 1; // {
            let mut map = BTreeMap::new();
            self.skip_ws();
            if self.chars.get(self.pos) == Some(&'}') {
                self.pos += 1;
                return Ok(Value::Object(map));
            }
            loop {
                self.skip_ws();
                let key = self.parse_string()?;
                self.skip_ws();
                if self.chars.get(self.pos) != Some(&':') {
                    return Err("expected :".to_string());
                }
                self.pos += 1;
                let v = self.parse_value()?;
                map.insert(key, v);
                self.skip_ws();
                match self.chars.get(self.pos) {
                    Some(',') => {
                        self.pos += 1;
                    }
                    Some('}') => {
                        self.pos += 1;
                        return Ok(Value::Object(map));
                    }
                    _ => return Err("expected , or }".to_string()),
                }
            }
        }
        fn parse_string(&mut self) -> Result<String, String> {
            if self.chars.get(self.pos) != Some(&'"') {
                return Err("expected string".to_string());
            }
            self.pos += 1;
            let mut s = String::new();
            while let Some(c) = self.chars.get(self.pos).copied() {
                self.pos += 1;
                match c {
                    '"' => return Ok(s),
                    '\\' => {
                        let e = self.chars.get(self.pos).copied();
                        self.pos += 1;
                        match e {
                            Some('"') => s.push('"'),
                            Some('\\') => s.push('\\'),
                            Some('/') => s.push('/'),
                            Some('n') => s.push('\n'),
                            Some('t') => s.push('\t'),
                            Some('r') => s.push('\r'),
                            Some('b') => s.push('\u{0008}'),
                            Some('f') => s.push('\u{000c}'),
                            Some('u') => {
                                let hex: String = (0..4)
                                    .filter_map(|_| self.chars.get(self.pos).copied())
                                    .collect();
                                if hex.len() != 4 {
                                    return Err("bad unicode".to_string());
                                }
                                self.pos += 4;
                                if let Ok(n) = u32::from_str_radix(&hex, 16) {
                                    if let Some(ch) = char::from_u32(n) {
                                        s.push(ch);
                                    }
                                }
                            }
                            _ => return Err("bad escape".to_string()),
                        }
                    }
                    _ => s.push(c),
                }
            }
            Err("unterminated string".to_string())
        }
        fn parse_number(&mut self) -> Result<Value, String> {
            let start = self.pos;
            if self.chars.get(self.pos) == Some(&'-') {
                self.pos += 1;
            }
            while let Some(c) = self.chars.get(self.pos) {
                if c.is_ascii_digit() || *c == '.' || *c == 'e' || *c == 'E' || *c == '+' || *c == '-' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            let s: String = self.chars[start..self.pos].iter().collect();
            s.parse::<f64>().map(Value::Number).map_err(|_| "bad number".to_string())
        }
    }
