{"command":"create","file_text":"//! Port of `src/ignoreFiles.js` plus a minimal picomatch-compatible glob
//! matcher.
//!
//! The original delegates glob matching to the `picomatch` package. We
//! reproduce the glob features jscodeshift relies on: literal characters,
//! `*` (matches within a path segment, not `/`), `?`, `**` (matches across
//! path separators), character classes `[...]`, and brace expansion of the
//! form `{a,b}`. The `dot` option (match leading-dot segments) is honored as
//! picomatch does.

use std::fs;
use std::path::Path;

/// Expand brace patterns like `{a,b,c}` into multiple glob patterns.
pub fn expand_braces(pattern: &str) -> Vec<String> {
    // Find the first top-level brace group.
    let bytes = pattern.as_bytes();
    let mut depth = 0i32;
    let mut start = None;
    let mut end = None;
    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'{' => {
                if depth == 0 && start.is_none() {
                    start = Some(i);
                }
                depth += 1;
            }
            b'}' => {
                depth -= 1;
                if depth == 0 {
                    end = Some(i);
                    break;
                }
            }
            _ => {}
        }
    }
    match (start, end) {
        (Some(s), Some(e)) => {
            let prefix = &pattern[..s];
            let suffix = &pattern[e + 1..];
            let inner = &pattern[s + 1..e];
            // Split inner on top-level commas.
            let mut parts: Vec<String> = Vec::new();
            let mut depth = 0i32;
            let mut cur = String::new();
            for ch in inner.chars() {
                match ch {
                    '{' => {
                        depth += 1;
                        cur.push(ch);
                    }
                    '}' => {
                        depth -= 1;
                        cur.push(ch);
                    }
                    ',' if depth == 0 => {
                        parts.push(cur.clone());
                        cur.clear();
                    }
                    _ => cur.push(ch),
                }
            }
            parts.push(cur);
            let mut out = Vec::new();
            for p in parts {
                let combined = format!("{}{}{}", prefix, p, suffix);
                out.extend(expand_braces(&combined));
            }
            out
        }
        _ => vec![pattern.to_string()],
    }
}

fn glob_to_regex(glob: &str, dot: bool) -> String {
    let mut re = String::from("^");
    let chars: Vec<char> = glob.chars().collect();
    let mut i = 0;
    let n = chars.len();
    while i < n {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < n && chars[i + 1] == '*' {
                    // ** segment
                    // consume any following slashes
                    let mut j = i + 2;
                    while j < n && chars[j] == '/' {
                        j += 1;
                    }
                    if j > i + 2 {
                        // **/  -> match zero or more path segments
                        re.push_str("(?:[^/]*(?:/|$))*");
                    } else {
                        // ** without trailing slash: match anything including slashes
                        re.push_str(".*");
                    }
                    i = j;
                    continue;
                } else {
                    // single * : match within a segment, not slash; respect dot
                    if dot {
                        re.push_str("[^/]*");
                    } else {
                        // do not match leading dot
                        re.push_str("[^/.][^/]*");
                    }
                    i += 1;
                    continue;
                }
            }
            '?' => {
                if dot {
                    re.push_str("[^/]");
                } else {
                    re.push_str("[^/.]");
                }
                i += 1;
                continue;
            }
            '[' => {
                // character class
                let mut class = String::from("[");
                let mut j = i + 1;
                if j < n && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                while j < n && chars[j] != ']' {
                    class.push(chars[j]);
                    j += 1;
                }
                if j < n {
                    class.push(']');
                    j += 1;
                    re.push_str(&class);
                    i = j;
                    continue;
                } else {
                    // no closing ], treat literally
                    re.push_str("\\[");
                    i += 1;
                    continue;
                }
            }
            '\\' => {
                if i + 1 < n {
                    re.push('\\');
                    re.push(chars[i + 1]);
                    i += 2;
                    continue;
                }
                re.push("\\\\");
                i += 1;
                continue;
            }
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' => {
                re.push('\\');
                re.push(c);
                i += 1;
                continue;
            }
            _ => {
                re.push(c);
                i += 1;
            }
        }
    }
    re.push('$');
    re
}

/// Compile a single glob pattern into a regex matcher.
pub struct Glob {
    regex: regex::Regex,
}

impl Glob {
    pub fn compile(pattern: &str, dot: bool) -> Self {
        let rx = regex::Regex::new(&glob_to_regex(pattern, dot))
            .expect("invalid glob");
        Glob { regex: rx }
    }
    pub fn is_match(&self, path: &str) -> bool {
        self.regex.is_match(path)
    }
}

pub struct Matcher {
    globs: Vec<Glob>,
}

impl Matcher {
    pub fn new(patterns: &[String], dot: bool) -> Self {
        let mut globs = Vec::new();
        for p in patterns {
            for expanded in expand_braces(p) {
                globs.push(Glob::compile(&expanded, dot));
            }
        }
        Matcher { globs }
    }
    pub fn is_match(&self, path: &str) -> bool {
        self.globs.iter().any(|g| g.is_match(path))
    }
    pub fn is_empty(&self) -> bool {
        self.globs.is_empty()
    }
}

pub struct Ignore {
    matchers: Vec<String>,
    compiled: Option<Matcher>,
}

impl Ignore {
    pub fn new() -> Self {
        Ignore {
            matchers: Vec::new(),
            compiled: None,
        }
    }

    fn add_pattern(&mut self, val: &str) {
        if !val.is_empty() && !val.starts_with('#') {
            let pattern = val;
            if !pattern.contains('/') {
                self.matchers.push(format!("**/{}", pattern));
            } else if pattern.ends_with('/') {
                self.matchers.push(format!("**/{}**", pattern));
                self.matchers.push(format!("{}**", pattern));
            }
            self.matchers.push(pattern.to_string());
        }
    }

    /// addIgnoreFromInput
    pub fn add(&mut self, input: Option<&Vec<String>>) {
        if let Some(input) = input {
            for p in input {
                self.add_pattern(p);
            }
        }
    }

    /// addIgnoreFromFile
    pub fn add_from_file(&mut self, input: Option<&Vec<String>>) {
        let mut lines: Vec<String> = Vec::new();
        if let Some(files) = input {
            for config in files {
                if let Ok(meta) = fs::metadata(config) {
                    if meta.is_file() {
                        if let Ok(content) = fs::read_to_string(config) {
                            for line in content.split('\n') {
                                // split on \r?\n -> also strip trailing \r
                                let line = line.trim_end_matches('\r');
                                lines.push(line.to_string());
                            }
                        }
                    }
                }
            }
        }
        for line in &lines {
            self.add_pattern(line);
        }
    }

    fn compiled(&mut self) -> &Matcher {
        if self.compiled.is_none() {
            self.compiled = Some(Matcher::new(&self.matchers, true));
        }
        self.compiled.as_ref().unwrap()
    }

    pub fn should_ignore(&mut self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let normalized = strip_traversal(path);
        let matcher = self.compiled();
        if matcher.is_match(path) {
            return true;
        }
        if normalized != path && matcher.is_match(&normalized) {
            return true;
        }
        false
    }
}

fn strip_traversal(path: &str) -> String {
    // Replicate path.replace(/^(?:\.\.?[/\\])+/,'')
    let mut s = path;
    loop {
        if s.starts_with("./") {
            s = &s[2..];
        } else if s.starts_with("../") {
            s = &s[3..];
        } else if s.starts_with(".\\") {
            s = &s[2..];
        } else if s.starts_with("..\\") {
            s = &s[3..];
        } else {
            break;
        }
    }
    s.to_string()
}

