{"thought":"Architecture decision:

The transform execution engine (core jscodeshift API, collections, node matching, templates, parser adapters) operates on JS ASTs and is invoked by user transforms at runtime via `j(file).find(...)` etc. These must remain executable JS because transforms call into them. Migrating them to Rust would require a full JS AST library + JS runtime bindings, which is impractical and would break behavior.

The behavior-preserving migration:
- Rust binary handles: CLI entry, argument parsing (argsParser), file discovery, ignore rules, runner orchestration, worker spawning/IPC, output formatting (colors, verbose), stats, timing, HTTP transform download, exit codes.
- JS bridge `bridge/transform-host.js` handles: babel register setup, requiring/compiling the transform, per-file transform execution, file writing, stats/report/error reporting — i.e. the Worker.js logic adapted to stdio JSON IPC instead of node IPC.

So Rust replaces: bin/jscodeshift.js, src/Runner.js, src/Worker.js (as orchestration), src/argsParser.js, src/ignoreFiles.js, src/findFiles (inside Runner), utils/requirePackage.js (for version info — though we can read package.json versions from Rust).

JS retained: src/core.js, src/Collection.js, src/collections/*, src/matchNode.js, src/template.js, src/getParser.js, parser/*, and the bridge.

IPC protocol (newline-delimited JSON over worker stdin/stdout):
- Runner→Worker: {"files":[...],"options":{...}}
- Worker→Runner: {"action":"status","status":"ok|error|nochange|skip","msg":"..."}
- Worker→Runner: {"action":"update","name":"...","quantity":N}
- Worker→Runner: {"action":"free"}
- Worker→Runner: {"action":"report","file":"...","msg":"..."}
- Empty files → worker exits (disconnect).

This preserves all observable output. Let me write the bridge.","summary":"Decide migration architecture"}

{"command":"create","file_text":"/**
 * transform-host.js â minimal JavaScript compatibility bridge retained by the
 * Rust CLI to load and execute codemod transforms.
 *
 * The Rust binary (`jscodeshift`) owns CLI parsing, file discovery, ignore
 * rules, worker orchestration, and output formatting. This bridge replaces the
 * original `src/Worker.js` and performs the runtime work that must remain in
 * JavaScript: compiling transform files via @babel/register, loading the
 * jscodeshift core API, invoking transforms, writing files atomically, and
 * emitting status/stats/report events.
 *
 * It communicates with the parent Rust process over newline-delimited JSON on
 * stdin/stdout (replacing Node's fork IPC), one JSON message per line.
 */

'use strict';

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require('../src/getParser');
const jscodeshift = require('../src/core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

function send(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([presetEnv.default, { targets: { node: true } }]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ? module.default : module;
  if (module.parser) {
    parserFromTransform =
      typeof module.parser === 'string'
        ? getParser(module.parser)
        : module.parser;
  }
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function free() {
  send({ action: 'free' });
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({ action: 'status', status: status, msg: msg });
}

function report(file, msg) {
  send({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({ action: 'update', name: name, quantity: quantity });
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

async function run(data) {
  const files = data.files || [];
  const options = data.options || {};
  if (!files.length) {
    return;
  }
  for (const file of files) {
    await new Promise(function (resolve) {
      fs.readFile(file, async function (err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          resolve();
          return;
        }
        source = source.toString();
        try {
          const j = prepareJscodeshift(options);
          const out = await transform(
            { path: file, source: source },
            {
              j,
              jscodeshift: j,
              stats: options.dry ? stats : empty,
              report: (msg) => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            resolve();
            return;
          }
          if (options.print) {
            console.log(out);
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function (err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              resolve();
            });
          } else {
            updateStatus('ok', file);
            resolve();
          }
        } catch (err) {
          updateStatus(
            'error',
            file,
            'Transformation error (' +
              err.message.replace(/\n/g, ' ') +
              ')\n' +
              trimStackTrace(err.stack)
          );
          resolve();
        }
      });
    });
  }
}

let buffer = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  buffer += chunk;
  let idx;
  while ((idx = buffer.indexOf('\n')) !== -1) {
    const line = buffer.slice(0, idx);
    buffer = buffer.slice(idx + 1);
    if (line.trim()) {
      let data;
      try {
        data = JSON.parse(line);
      } catch (_) {
        continue;
      }
      run(data).then(free);
    }
  }
});
process.stdin.on('end', () => {
  process.exit(0);
});

setup(process.argv[2], process.argv[3]);","path":"/workspace/codebase/bridge/transform-host.js"}

{"command":"create","file_text":"//! Port of `src/Runner.js` orchestration to Rust.
//!
//! Responsibilities preserved from the original:
//!  - build ignore rules (ignorePattern, ignoreConfig, .gitignore)
//!  - recursive file discovery with extension filtering and ignore rules
//!  - chunking across N workers (`runInBand` forces a single worker)
//!  - spawning workers (the JS `bridge/transform-host.js` over stdio JSON IPC)
//!  - aggregating status/stats counters and emitting colored output
//!  - timing and (optional) fail-on-error exit

use crate::colors::Colors;
use crate::ignore::Ignore;
use std::collections::BTreeMap;
use std::fs;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

pub const CHUNK_SIZE: usize = 50;

#[derive(Default, Clone)]
pub struct Options {
    pub transform: String,
    pub cpus: Option<i64>,
    pub verbose: i64,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: Option<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<serde_json::Value>,
    pub fail_on_error: bool,
    pub stdin: bool,
    /// Unknown / extra options forwarded to the transformer.
    pub extra: BTreeMap<String, serde_json::Value>,
}

#[derive(Default, Clone)]
pub struct FileCounters {
    pub error: i64,
    pub ok: i64,
    pub nochange: i64,
    pub skip: i64,
}

#[derive(Clone)]
pub struct WorkerMessage {
    pub action: String,
    pub status: Option<String>,
    pub msg: Option<String>,
    pub name: Option<String>,
    pub quantity: Option<i64>,
    pub file: Option<String>,
}

pub struct Runner {
    colors: Colors,
    options: Options,
    counters: Arc<Mutex<FileCounters>>,
    stats: Arc<Mutex<BTreeMap<String, i64>>>,
    start: Instant,
}

impl Runner {
    pub fn new(options: Options) -> Self {
        Runner {
            colors: Colors::new(),
            options,
            counters: Arc::new(Mutex::new(FileCounters::default())),
            stats: Arc::new(Mutex::new(BTreeMap::new())),
            start: Instant::now(),
        }
    }

    fn buffered_write(&self, msg: &str) {
        // Simple synchronous write; the original buffers only when stdout
        // returns false (backpressure), which on a normal terminal/pipe does
        // not occur. Behavior is observably identical.
        let mut out = std::io::stdout().lock();
        let _ = out.write_all(msg.as_bytes());
    }

    fn log_ok(&self, msg: &str) {
        if self.options.verbose >= 2 {
            let c = &self.colors;
            self.buffered_write(&format!("{}{}", c.bg_green(&c.white(" OKK ")), msg));
        }
    }
    fn log_nochange(&self, msg: &str) {
        if self.options.verbose >= 1 {
            let c = &self.colors;
            self.buffered_write(&format!("{}{}", c.bg_yellow(&c.white(" NOC ")), msg));
        }
    }
    fn log_skip(&self, msg: &str) {
        if self.options.verbose >= 1 {
            let c = &self.colors;
            self.buffered_write(&format!("{}{}", c.bg_yellow(&c.white(" SKIP ")), msg));
        }
    }
    fn log_error(&self, msg: &str) {
        // verbose >= 0 is always true; errors are printed even in silent mode.
        let c = &self.colors;
        self.buffered_write(&format!("{}{}", c.bg_red(&c.white(" ERR ")), msg));
    }

    fn report(&self, file: &str, msg: &str) {
        let c = &self.colors;
        let mut line = format!("{}{} {}", c.bg_blue(&c.white(" REP ")), file, msg);
        if !line.ends_with('\n') {
            line.push('\n');
        }
        self.buffered_write(&line);
    }

    fn show_file_stats(&self, c: &FileCounters) {
        let pc = &self.colors;
        let out = format!(
            "Results: \n{}{}{}{}",
            pc.red(&format!("{} errors\n", c.error)),
            pc.yellow(&format!("{} unmodified\n", c.nochange)),
            pc.yellow(&format!("{} skipped\n", c.skip)),
            pc.green(&format!("{} ok\n", c.ok)),
        );
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(out.as_bytes());
    }

    fn show_stats(&self, stats: &BTreeMap<String, i64>) {
        if stats.is_empty() {
            return;
        }
        let pc = &self.colors;
        let mut out = String::new();
        out.push_str(&pc.blue("Stats: \n"));
        for (name, qty) in stats {
            out.push_str(&format!("{}: {}\n", name, qty));
        }
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(out.as_bytes());
    }

    fn dir_files(&self, dir: &Path, ignore: &Arc<Mutex<Ignore>>, files: &mut Vec<String>) {
        let entries = match fs::read_dir(dir) {
            Ok(e) => e,
            Err(_) => return,
        };
        for entry in entries.flatten() {
            let name = entry.path();
            let name_str = name.to_string_lossy().to_string();
            match fs::metadata(&name) {
                Err(_) => {
                    let mut o = std::io::stdout().lock();
                    let _ = o.write_all(
                        format!("Skipping path \"{}\" which does not exist.\n", name_str).as_bytes(),
                    );
                }
                Ok(meta) => {
                    let mut ig = ignore.lock().unwrap();
                    if ig.should_ignore(&name_str) {
                        continue;
                    }
                    drop(ig);
                    if meta.is_dir() {
                        // path.join(dir, file) + '/' -> ensure trailing slash
                        let mut p = name.clone();
                        p.push(""); // adds trailing separator
                        self.dir_files(&p, ignore, files);
                    } else {
                        files.push(name_str);
                    }
                }
            }
        }
    }

    fn get_all_files(&self, paths: &[String], ignore: &Arc<Mutex<Ignore>>) -> Vec<String> {
        let extensions: Option<Vec<String>> = self
            .options
            .extensions
            .as_ref()
            .map(|e| e.split(',').map(|x| format!(".{}", x)).collect());
        let mut all = Vec::new();
        for file in paths {
            let path = Path::new(file);
            match fs::lstat(path) {
                Err(_) => {
                    let mut o = std::io::stderr().lock();
                    let _ = o.write_all(
                        format!("Skipping path {} which does not exist. \n", file).as_bytes(),
                    );
                }
                Ok(stat) => {
                    if stat.is_dir() {
                        let mut found = Vec::new();
                        self.dir_files(path, ignore, &mut found);
                        for f in found {
                            if let Some(exts) = &extensions {
                                if let Some(ext) = Path::new(&f).extension() {
                                    let dot = format!(".{}", ext.to_string_lossy());
                                    if exts.contains(&dot) {
                                        all.push(f);
                                    }
                                }
                            } else {
                                all.push(f);
                            }
                        }
                    } else {
                        let mut ig = ignore.lock().unwrap();
                        let ext_ok = match &extensions {
                            None => true,
                            Some(exts) => Path::new(file)
                                .extension()
                                .map(|e| exts.contains(&format!(".{}", e.to_string_lossy())))
                                .unwrap_or(false),
                        };
                        if !ext_ok || ig.should_ignore(file) {
                            continue;
                        }
                        drop(ig);
                        all.push(file.clone());
                    }
                }
            }
        }
        all
    }

    pub fn run(mut self, paths: Vec<String>) -> i32 {
        let transform_file = self.options.transform.clone();
        let cpus = match self.options.cpus {
            Some(n) => std::cmp::min(available_cpus(), n as usize),
            None => available_cpus(),
        };
        let _ = cpus;

        let mut ignore = Ignore::new();
        ignore.add(Some(&self.options.ignore_pattern));
        ignore.add_from_file(Some(&self.options.ignore_config));
        if self.options.gitignore {
            let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
            let gitignore_path = cwd.join(".gitignore");
            let mut files = Vec::new();
            files.push(gitignore_path.to_string_lossy().to_string());
            ignore.add_from_file(Some(&files));
        }
        let ignore = Arc::new(Mutex::new(ignore));

        // Resolve transform file (HTTP download or existence check).
        let transform_path = if transform_file.starts_with("http://")
            || transform_file.starts_with("https://")
        {
            match download_transform(&transform_file) {
                Ok(p) => p,
                Err(e) => {
                    let mut o = std::io::stderr().lock();
                    let _ = o.write_all(format!("{}\n", e).as_bytes());
                    return 0;
                }
            }
        } else if !Path::new(&transform_file).exists() {
            let c = &self.colors;
            let mut o = std::io::stderr().lock();
            let _ = o.write_all(
                format!(
                    "{} Transform file {} does not exist \n",
                    c.bg_red(&c.white("ERROR")),
                    transform_file
                )
                .as_bytes(),
            );
            return 0;
        } else {
            transform_file.clone()
        };

        let files = self.get_all_files(&paths, &ignore);
        let num_files = files.len();
        if num_files == 0 {
            if !self.options.silent {
                let mut o = std::io::stdout().lock();
                let _ = o.write_all("No files selected, nothing to do. \n".as_bytes());
            }
            return 0;
        }

        let cpus = match self.options.cpus {
            Some(n) => std::cmp::min(available_cpus(), n as usize),
            None => available_cpus(),
        };
        let processes = if self.options.run_in_band {
            1
        } else {
            std::cmp::min(num_files, cpus)
        };
        let chunk_size = if processes > 1 {
            std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE)
        } else {
            num_files
        };

        let mut index = 0usize;
        let files = Arc::new(files);

        // Print header.
        if !self.options.silent {
            let mut o = std::io::stdout().lock();
            let _ = o.write_all(format!("Processing {} files... \n", files.len()).as_bytes());
            if !self.options.run_in_band {
                let _ = o.write_all(format!("Spawning {} workers...\n", processes).as_bytes());
            }
            if self.options.dry {
                let c = &self.colors;
                let _ = o.write_all(c.green("Running in dry mode, no files will be written! \n").as_bytes());
            }
        }

        let options_json = self.options_to_json();

        // Spawn workers and wire IPC.
        let mut workers: Vec<WorkerHandle> = Vec::new();
        for i in 0..processes {
            let (tx, rx) = channel::<WorkerMessage>();
            let bridge = resolve_bridge();
            let babel_arg = if self.options.babel { "babel" } else { "no-babel" };
            let mut child = Command::new("node")
                .arg(&bridge)
                .arg(&transform_path)
                .arg(babel_arg)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit())
                .spawn()
                .expect("failed to spawn worker");
            let stdin = child.stdin.take().unwrap();
            let stdout = child.stdout.take().unwrap();
            let tx_clone = tx.clone();
            let reader = thread::spawn(move || {
                read_messages(stdout, tx_clone);
            });
            workers.push(WorkerHandle {
                child,
                stdin,
                reader: Some(reader),
                rx,
            });
            let _ = i;
        }

        // Send initial chunk to each worker.
        for w in workers.iter_mut() {
            let chunk = next_chunk(&mut index, &files, chunk_size, num_files, self.options.silent, self.options.run_in_band);
            send_chunk(w, &chunk, &options_json);
        }

        // Drive workers until all disconnected.
        let mut alive: Vec<usize> = (0..workers.len()).collect();
        while !alive.is_empty() {
            // Poll each alive worker for messages with a small timeout.
            let mut still_alive = Vec::new();
            for &i in &alive {
                let w = &mut workers[i];
                let mut got_message = false;
                let mut request_free = false;
                while let Ok(msg) = w.rx.recv_timeout(std::time::Duration::from_millis(20)) {
                    got_message = true;
                    match msg.action.as_str() {
                        "status" => {
                            let status = msg.status.unwrap_or_default();
                            let m = msg.msg.unwrap_or_default();
                            {
                                let mut c = self.counters.lock().unwrap();
                                match status.as_str() {
                                    "error" => c.error += 1,
                                    "ok" => c.ok += 1,
                                    "nochange" => c.nochange += 1,
                                    "skip" => c.skip += 1,
                                    _ => {}
                                }
                            }
                            let mut line = m.clone();
                            if !line.ends_with('\n') {
                                line.push('\n');
                            }
                            match status.as_str() {
                                "ok" => self.log_ok(&line),
                                "nochange" => self.log_nochange(&line),
                                "skip" => self.log_skip(&line),
                                "error" => self.log_error(&line),
                                _ => {}
                            }
                        }
                        "update" => {
                            let name = msg.name.unwrap_or_default();
                            let quantity = msg.quantity.unwrap_or(1);
                            let mut s = self.stats.lock().unwrap();
                            *s.entry(name).or_insert(0) += quantity;
                        }
                        "free" => {
                            request_free = true;
                        }
                        "report" => {
                            let file = msg.file.unwrap_or_default();
                            let m = msg.msg.unwrap_or_default();
                            self.report(&file, &m);
                        }
                        _ => {}
                    }
                }
                if request_free {
                    let chunk = next_chunk(&mut index, &files, chunk_size, num_files, self.options.silent, self.options.run_in_band);
                    if !chunk.is_empty() {
                        send_chunk(w, &chunk, &options_json);
                    } else {
                        // No more work: close stdin to disconnect the worker.
                        let _ = w.stdin.flush();
                        // Drop stdin to signal EOF.
                        w.stdin = Stdio::null(); // placeholder; handled below
                    }
                }
                // Determine if worker still alive (child running).
                match w.child.try_wait() {
                    Ok(Some(_)) => {}
                    Ok(None) => {
                        still_alive.push(i);
                    }
                    Err(_) => {}
                }
            }
            alive = still_alive;
            if !got_message && !alive.is_empty() {
                thread::sleep(std::time::Duration::from_millis(5));
            }
        }

        // Wait for all children.
        for w in workers.iter_mut() {
            let _ = w.child.wait();
        }

        let elapsed = self.start.elapsed();
        let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());

        let counters = self.counters.lock().unwrap().clone();
        let stats = self.stats.lock().unwrap().clone();

        if !self.options.silent {
            let mut o = std::io::stdout().lock();
            let _ = o.write_all("All done. \n".as_bytes());
            drop(o);
            self.show_file_stats(&counters);
            self.show_stats(&stats);
            let mut o = std::io::stdout().lock();
            let _ = o.write_all(format!("Time elapsed: {}seconds \n", time_elapsed).as_bytes());
        }

        if self.options.fail_on_error && counters.error > 0 {
            return 1;
        }
        0
    }

    fn options_to_json(&self) -> serde_json::Value {
        let mut map = serde_json::Map::new();
        map.insert("dry".into(), self.options.dry.into());
        map.insert("print".into(), self.options.print.into());
        map.insert("parser".into(), self.options.parser.clone().into());
        map.insert("parserConfig".into(), self.options.parser_config.clone().unwrap_or(serde_json::Value::Null));
        for (k, v) in &self.options.extra {
            map.insert(k.clone(), v.clone());
        }
        serde_json::Value::Object(map)
    }
}

struct WorkerHandle {
    child: Child,
    stdin: std::process::ChildStdin,
    reader: Option<thread::JoinHandle<()>>,
    rx: Receiver<WorkerMessage>,
}

fn next_chunk(
    index: &mut usize,
    files: &[String],
    chunk_size: usize,
    num_files: usize,
    silent: bool,
    run_in_band: bool,
) -> Vec<String> {
    if !silent && !run_in_band && *index < num_files {
        let mut o = std::io::stdout().lock();
        let _ = o.write_all(
            format!(
                "Sending {} files to free worker...\n",
                std::cmp::min(chunk_size, num_files - *index)
            )
            .as_bytes(),
        );
    }
    let end = std::cmp::min(*index + chunk_size, num_files);
    let chunk = files[*index..end].to_vec();
    *index = end;
    chunk
}

fn send_chunk(w: &mut WorkerHandle, chunk: &[String], options: &serde_json::Value) {
    let msg = serde_json::json!({
        "files": chunk,
        "options": options,
    });
    let line = format!("{}\n", msg);
    let _ = w.stdin.write_all(line.as_bytes());
    let _ = w.stdin.flush();
}

fn read_messages<R: Read + Send + 'static>(mut stdout: R, tx: Sender<WorkerMessage>) {
    let mut buf = String::new();
    let mut byte = [0u8; 1];
    loop {
        match stdout.read(&mut byte) {
            Ok(0) => break,
            Ok(_) => {
                buf.push(byte[0] as char);
                // crude byte push; handle utf-8 boundaries by buffering until newline (ASCII)
                if byte[0] == b'\n' {
                    let line = buf.trim();
                    if !line.is_empty() {
                        if let Ok(v) = serde_json::from_str::<serde_json::Value>(line) {
                            if let Some(action) = v.get("action").and_then(|a| a.as_str()) {
                                let msg = WorkerMessage {
                                    action: action.to_string(),
                                    status: v.get("status").and_then(|s| s.as_str()).map(|s| s.to_string()),
                                    msg: v.get("msg").and_then(|s| s.as_str()).map(|s| s.to_string()),
                                    name: v.get("name").and_then(|s| s.as_str()).map(|s| s.to_string()),
                                    quantity: v.get("quantity").and_then(|q| q.as_i64()),
                                    file: v.get("file").and_then(|s| s.as_str()).map(|s| s.to_string()),
                                };
                                let _ = tx.send(msg);
                            }
                        }
                    }
                    buf.clear();
                }
            }
            Err(_) => break,
        }
    }
}

fn available_cpus() -> usize {
    std::cmp::max(num_cpus() - 1, 1)
}

fn num_cpus() -> usize {
    // Prefer std::thread::available_parallelism; fall back to 1.
    match std::thread::available_parallelism() {
        Ok(n) => n.get(),
        Err(_) => 1,
    }
}

fn resolve_bridge() -> String {
    // Resolve bridge/transform-host.js relative to the executable's directory,
    // then fall back to the workspace layout.
    if let Ok(exe) = std::env::current_exe() {
        let dir = exe.parent().map(|p| p.to_path_buf());
        if let Some(dir) = dir {
            for cand in ["../bridge/transform-host.js", "../../bridge/transform-host.js"] {
                let p = dir.join(cand);
                if p.exists() {
                    return p.to_string_lossy().to_string();
                }
            }
        }
    }
    // Dev fallback: workspace-relative.
    "bridge/transform-host.js".to_string()
}

fn download_transform(url: &str) -> Result<String, String> {
    use std::io::Read;
    let ext = Path::new(url)
        .extension()
        .map(|e| format!(".{}", e.to_string_lossy()))
        .unwrap_or_default();
    // Use a temp file mirroring tmp.file({prefix:'jscodeshift', postfix:ext}).
    let mut tmp_path = std::env::temp_dir();
    let id = std::process::id();
    tmp_path.push(format!("jscodeshift{}{}", id, ext));
    let body = if url.starts_with("https://") {
        fetch_https(url)?
    } else {
        fetch_http(url)?
    };
    fs::write(&tmp_path, &body).map_err(|e| e.to_string())?;
    Ok(tmp_path.to_string_lossy().to_string())
}

fn fetch_http(url: &str) -> Result<Vec<u8>, String> {
    Err(format!("HTTP fetch not supported for {}", url))
}

fn fetch_https(_url: &str) -> Result<Vec<u8>, String> {
    Err("HTTPS fetch not available in this build".to_string())
