{"command":"create","file_text":"//! Runtime version reporting, porting `utils/requirePackage.js` and the
//! `--version` callback from `bin/jscodeshift.js`.
//!
//! `requirePackage` walks up from the resolved entry of a package to find the
//! nearest `package.json` whose `name` matches. We replicate this by locating
//! the package via Node's resolution (so installed/transpiled packages resolve
//! exactly as the original) and reading its `package.json`.

use std::path::{Path, PathBuf};

/// Read the `version` field of a package located under `node_modules/<name>`,
/// searching upward from the current directory (mirroring Node resolution from
/// cwd) and then from the jscodeshift install root.
pub fn package_version(name: &str) -> String {
    if let Some(v) = resolve_from_cwd(name) {
        return v;
    }
    if let Some(v) = resolve_from_install_root(name) {
        return v;
    }
    String::new()
}

fn read_pkg_version(pkg_path: &Path, expected_name: &str) -> Option<String> {
    let content = std::fs::read_to_string(pkg_path).ok()?;
    let value = crate::version::serde_parse(&content).ok()?;
    let obj = value.as_object()?;
    let name = obj.get("name")?.as_str()?;
    if name != expected_name {
        return None;
    }
    let version = obj.get("version")?.as_str()?;
    Some(version.to_string())
}

fn resolve_from_cwd(name: &str) -> Option<String> {
    let cwd = std::env::current_dir().ok()?;
    let mut dir: Option<&Path> = Some(&cwd);
    let mut dirs: Vec<PathBuf> = Vec::new();
    while let Some(d) = dir {
        dirs.push(d.to_path_buf());
        dir = d.parent();
    }
    for d in dirs {
        let cand = d.join("node_modules").join(name).join("package.json");
        if cand.exists() {
            if let Some(v) = read_pkg_version(&cand, name) {
                return Some(v);
            }
        }
    }
    None
}

fn resolve_from_install_root(name: &str) -> Option<String> {
    // The Rust binary is installed alongside the JS package; resolve relative
    // to the executable, then walk up looking for node_modules/<name>.
    let exe = std::env::current_exe().ok()?;
    let mut dir: Option<&Path> = exe.parent();
    let mut dirs: Vec<PathBuf> = Vec::new();
    while let Some(d) = dir {
        dirs.push(d.to_path_buf());
        dir = d.parent();
    }
    for d in dirs {
        let cand = d.join("node_modules").join(name).join("package.json");
        if cand.exists() {
            if let Some(v) = read_pkg_version(&cand, name) {
                return Some(v);
            }
        }
    }
    None
}

/// Minimal JSON parse sufficient for package.json files (delegates to serde).
pub fn serde_parse(input: &str) -> Result<serde_json::Value, String> {
    serde_json::from_str(input).map_err(|e| e.to_string())
}

/// Build the `--version` output string, matching the original callback.
pub fn version_string(jscodeshift_version: &str) -> String {
    let babel = package_version("@babel/core");
    let babylon = package_version("@babel/parser");
    let flow = package_version("flow-parser");
    let recast = package_version("recast");
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        jscodeshift_version, babel, babylon, flow, recast
    )
}","path":"/workspace/codebase/rust/src/version.rs"}

