const PKG_VERSION: &str = "17.4.0";

fn fn_number(v: &str) -> Value {
    v.parse::<f64>().map(Value::Number).unwrap_or(Value::String(v.to_string()))
}

fn fn_parser_config(v: &str) -> Value {
    // process: file => JSON.parse(fs.readFileSync(file))
    match std::fs::read_to_string(v) {
        Ok(content) => match serde_json::from_str::<serde_json::Value>(&content) {
            Ok(val) => json_to_value(val),
            Err(_) => Value::String(v.to_string()),
        },
        Err(_) => Value::String(v.to_string()),
    }
}

fn json_to_value(v: serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::Null,
        serde_json::Value::Bool(b) => Value::Bool(b),
        serde_json::Value::Number(n) => Value::Number(n.as_f64().unwrap_or(0.0)),
        serde_json::Value::String(s) => Value::String(s),
        serde_json::Value::Array(a) => Value::Array(a.into_iter().map(json_to_value).collect()),
        serde_json::Value::Object(o) => {
            let mut m = BTreeMap::new();
            for (k, v) in o {
                m.insert(k, json_to_value(v));
            }
            Value::Object(m)
        }
    }
}

fn value_to_json(v: &Value) -> serde_json::Value {
    match v {
        Value::Null => serde_json::Value::Null,
        Value::Bool(b) => serde_json::Value::Bool(*b),
        Value::Number(n) => serde_json::Number::from_f64(*n)
            .map(serde_json::Value::Number)
            .unwrap_or(serde_json::Value::Null),
        Value::String(s) => serde_json::Value::String(s.clone()),
        Value::Array(a) => serde_json::Value::Array(a.iter().map(value_to_json).collect()),
        Value::Object(o) => {
            let mut m = serde_json::Map::new();
            for (k, v) in o {
                m.insert(k.clone(), value_to_json(v));
            }
            serde_json::Value::Object(m)
        }
    }
}

