    let ignore_pattern = value_as_string_list(opts.get("ignorePattern").unwrap_or(&Value::Array(vec![])));
    let ignore_config = value_as_string_list(opts.get("ignoreConfig").unwrap_or(&Value::Array(vec![])));
    let gitignore = value_as_bool(opts.get("gitignore").unwrap_or(&Value::Bool(false)), false);
    let run_in_band = value_as_bool(opts.get("runInBand").unwrap_or(&Value::Bool(false)), false);
    let silent = value_as_bool(opts.get("silent").unwrap_or(&Value::Bool(false)), false);
    let parser_name = value_as_string(opts.get("parser").unwrap_or(&Value::String("babel".to_string())))
        .unwrap_or_else(|| "babel".to_string());
    let parser_config = opts.get("parserConfig").map(value_to_json);
    let fail_on_error = value_as_bool(opts.get("failOnError").unwrap_or(&Value::Bool(false)), false);
    let stdin = value_as_bool(opts.get("stdin").unwrap_or(&Value::Bool(false)), false);

