{"command":"create","path":"/workspace/codebase/rust/src/paths.rs","file_text":"//! Shared path resolution. The first-party JS package and its `node_modules`
//! live in a single "package root" directory. We locate that root by finding
//! the `bridge/transform-host.js` bridge file (the same logic the runner uses
//! to spawn the transform host), then derive the package root as its parent.
//! This mirrors the JS CLI, where `require.resolve('<pkg>')` resolves relative
//! to the installed package, independent of the caller's working directory.

use std::env;
use std::path::{Path, PathBuf};

/// Return the package root directory (containing `bridge/`, `bin/`,
/// `node_modules/`). Resolution mirrors `resolve_bridge` in the runner.
pub fn package_root() -> PathBuf {
    if let Ok(p) = env::var("JSCODESHIFT_BRIDGE") {
        if Path::new(&p).exists() {
            if let Some(root) = bridge_root(&PathBuf::from(p)) {
                return root;
            }
        }
    }
    if let Ok(exe) = env::current_exe() {
        if let Some(dir) = exe.parent().map(|p| p.to_path_buf()) {
            for cand in [
                "bridge/transform-host.js",
                "../bridge/transform-host.js",
                "../../bridge/transform-host.js",
                "../codebase/bridge/transform-host.js",
                "../../codebase/bridge/transform-host.js",
                "../../../codebase/bridge/transform-host.js",
                "../resources/bridge/transform-host.js",
            ] {
                let p = dir.join(cand);
                if p.exists() {
                    if let Some(root) = bridge_root(&p) {
                        return root;
                    }
                }
            }
        }
    }
    if Path::new("bridge/transform-host.js").exists() {
        if let Some(root) = bridge_root(&PathBuf::from("bridge/transform-host.js")) {
            return root;
        }
    }
    // Fallback: cwd.
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn bridge_root(bridge: &Path) -> Option<PathBuf> {
    let abs = if bridge.is_absolute() {
        bridge.to_path_buf()
    } else {
        env::current_dir().ok()?.join(bridge)
    };
    // bridge/transform-host.js -> package root is the parent of `bridge/`.
    abs.parent()?.parent().map(Path::to_path_buf)
}

/// Resolve a package's `package.json` version by walking up from cwd, then
/// from the package root, mirroring Node's resolution from both the caller's
/// cwd and the jscodeshift install location.
pub fn package_version(name: &str) -> String {
    if let Some(v) = resolve_from_cwd(name) {
        return v;
    }
    if let Some(v) = resolve_from_dir(name, &package_root()) {
        return v;
    }
    String::new()
}

fn read_pkg_version(pkg_path: &Path, expected_name: &str) -> Option<String> {
    let content = std::fs::read_to_string(pkg_path).ok()?;
    let value = serde_json::from_str::<serde_json::Value>(&content).ok()?;
    let obj = value.as_object()?;
    let name = obj.get("name")?.as_str()?;
    if name != expected_name {
        return None;
    }
    let version = obj.get("version")?.as_str()?;
    Some(version.to_string())
}

fn resolve_from_cwd(name: &str) -> Option<String> {
    let cwd = env::current_dir().ok()?;
    resolve_from_dir(name, &cwd)
}

fn resolve_from_dir(name: &str, start: &Path) -> Option<String> {
    let mut dir: Option<&Path> = Some(start);
    let mut dirs: Vec<PathBuf> = Vec::new();
    while let Some(d) = dir {
        dirs.push(d.to_path_buf());
        dir = d.parent();
    }
    for d in dirs {
        let cand = d.join("node_modules").join(name).join("package.json");
        if cand.exists() {
            if let Some(v) = read_pkg_version(&cand, name) {
                return Some(v);
            }
        }
    }
    None
}"}

