{"command":"str_replace","path":"/workspace/codebase/rust/src/paths.rs","old_str":"/// Resolve a package's `package.json` version by walking up from cwd, then","new_str":"/// Lexically resolve a path relative to the current working directory,
/// mirroring Node's `path.resolve`. Unlike `std::fs::canonicalize` this does
/// not require the path to exist and does not resolve symlinks; it only
/// normalizes `.`/`..` segments and joins against cwd for relative inputs.
pub fn node_resolve(p: &str) -> String {
    let base = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let joined = if Path::new(p).is_absolute() {
        PathBuf::from(p)
    } else {
        base.join(p)
    };
    normalize(&joined).to_string_lossy().to_string()
}

fn normalize(p: &Path) -> PathBuf {
    let mut out: Vec<std::ffi::OsString> = Vec::new();
    for comp in p.components() {
        use std::path::Component;
        match comp {
            Component::CurDir => {}
            Component::ParentDir => {
                if out.last().map(|c| c.as_os_str() != "..").unwrap_or(false) {
                    out.pop();
                } else {
                    out.push(comp.as_os_str().to_os_string());
                }
            }
            c => out.push(c.as_os_str().to_os_string()),
        }
    }
    let mut buf = PathBuf::new();
    for c in out {
        buf.push(c);
    }
    if buf.as_os_str().is_empty() {
        PathBuf::from(".")
    } else {
        buf
    }
}

